"""Filter expressions of export --where (docs/export.md, section 5)."""

import re
from datetime import datetime
from decimal import Decimal

from tally.errors import UsageError
from tally.store.values import parse_date, parse_datetime, typed

KEYWORDS = {"and", "or", "not", "in", "is", "null", "true", "false"}
_TOKEN = re.compile(
    r"""\s*(?:
      (?P<str>'(?:[^']|'')*')
    | (?P<num>-?\d+(?:\.\d+)?(?![A-Za-z0-9_.]))
    | (?P<word>[A-Za-z_][A-Za-z0-9_.]*)
    | (?P<op><=|>=|!=|=|<|>|~)
    | (?P<punct>[(),])
    )""",
    re.X,
)


def _tokenize(text):
    pos, out = 0, []
    while True:
        m = re.compile(r"\s*").match(text, pos)
        pos = m.end()
        if pos >= len(text):
            return out
        m = _TOKEN.match(text, pos)
        if not m:
            raise UsageError(f"--where: unexpected text at {text[pos:pos + 10]!r}")
        pos = m.end()
        kind = m.lastgroup
        val = m.group(kind)
        if kind == "word" and val.lower() in KEYWORDS:
            kind, val = "kw", val.lower()
        elif kind == "str":
            val = val[1:-1].replace("''", "'")
        elif kind == "num":
            val = Decimal(val)
        out.append((kind, val))


class _Parser:
    def __init__(self, text, schema):
        self.toks = _tokenize(text)
        self.i = 0
        self.schema = schema

    def peek(self, k=0):
        j = self.i + k
        return self.toks[j] if j < len(self.toks) else (None, None)

    def take(self):
        t = self.peek()
        if t[0] is None:
            raise UsageError("--where: unexpected end of expression")
        self.i += 1
        return t

    def kw(self, word, k=0):
        return self.peek(k) == ("kw", word)

    def expect(self, kind, val):
        if self.peek() != (kind, val):
            raise UsageError(f"--where: expected {val!r}")
        self.i += 1

    def parse(self):
        if not self.toks:
            raise UsageError("--where: empty expression")
        node = self.or_expr()
        if self.i != len(self.toks):
            raise UsageError("--where: unexpected text after expression")
        return node

    def or_expr(self):
        parts = [self.and_expr()]
        while self.kw("or"):
            self.i += 1
            parts.append(self.and_expr())
        return lambda r: any(p(r) for p in parts)

    def and_expr(self):
        parts = [self.not_expr()]
        while self.kw("and"):
            self.i += 1
            parts.append(self.not_expr())
        return lambda r: all(p(r) for p in parts)

    def not_expr(self):
        if self.kw("not"):
            self.i += 1
            inner = self.not_expr()
            return lambda r: not inner(r)
        return self.primary()

    def primary(self):
        if self.peek() == ("punct", "("):
            self.i += 1
            node = self.or_expr()
            self.expect("punct", ")")
            return node
        return self.test()

    def literal(self, field):
        kind, val = self.take()
        if kind == "kw" and val in ("true", "false"):
            kind, val = "bool", val == "true"
        elif kind not in ("str", "num"):
            raise UsageError("--where: literal expected")
        return _convert(field, kind, val)

    def test(self):
        kind, path = self.take()
        if kind != "word":
            raise UsageError("--where: field path expected")
        field = self.schema.field(path)
        if self.kw("is"):
            self.i += 1
            neg = False
            if self.kw("not"):
                self.i += 1
                neg = True
            self.expect("kw", "null")
            return lambda r: (typed(r, field) is not None) == neg if False else ((typed(r, field) is None) != neg)
        negate = False
        if self.kw("not"):
            self.i += 1
            negate = True
            if not self.kw("in"):
                raise UsageError("--where: 'in' expected after 'not'")
        if self.kw("in"):
            self.i += 1
            self.expect("punct", "(")
            lits = [self.literal(field)]
            while self.peek() == ("punct", ","):
                self.i += 1
                lits.append(self.literal(field))
            self.expect("punct", ")")

            def in_test(r):
                v = typed(r, field)
                if v is None:
                    return False
                return (v not in lits) if negate else (v in lits)
            return in_test
        kind, op = self.take()
        if kind != "op":
            raise UsageError("--where: operator expected")
        if op == "~":
            if field.type != "string":
                raise UsageError("--where: '~' needs a string field")
        if field.type == "bool" and op not in ("=", "!="):
            raise UsageError("--where: bool fields allow only = and !=")
        lit = self.literal(field)
        if op == "~":
            return lambda r: (lambda v: v is not None and lit in v)(typed(r, field))
        cmp = _OPS[op]

        def test(r):
            v = typed(r, field)
            return v is not None and cmp(v, lit)
        return test


_OPS = {
    "=": lambda a, b: a == b,
    "!=": lambda a, b: a != b,
    "<": lambda a, b: a < b,
    "<=": lambda a, b: a <= b,
    ">": lambda a, b: a > b,
    ">=": lambda a, b: a >= b,
    "~": None,
}


def _convert(field, kind, val):
    t = field.type
    try:
        if t in ("int", "decimal") and kind == "num":
            return val
        if t == "string" and kind == "str":
            return val
        if t == "bool" and kind == "bool":
            return val
        if t == "date" and kind == "str":
            return parse_date(val)
        if t == "datetime" and kind == "str":
            if len(val) == 10:
                return datetime.combine(parse_date(val), datetime.min.time())
            return parse_datetime(val)
    except ValueError:
        raise UsageError(f"--where: invalid value for {field.name}: {val!r}") from None
    raise UsageError(f"--where: literal does not suit {t} field {field.name}")


def parse_where(text, schema):
    """Expression text -> predicate over raw records."""
    return _Parser(text, schema).parse()
