"""tally export COLLECTION: records as CSV text (docs/export.md)."""

from tally.errors import UsageError
from tally.exporting.sort import parse_sort, sort_records
from tally.exporting.text import check_delimiter, check_null, field_text, value_text
from tally.exporting.where import parse_where
from tally.fmt.locales import load_locale
from tally.store.values import typed
from tally.textio import output_path, write_stdout, write_text_file

NAME = "export"
HELP = "write records of a collection as CSV"


def register(p) -> None:
    p.add_argument("collection")
    p.add_argument("--columns", metavar="SPEC", help="PATH or PATH=NAME items, comma-separated (all fields when left out)")
    p.add_argument("--where", metavar="EXPR", help="filter expression (all records when left out)")
    p.add_argument("--sort", metavar="SPEC", help="sort keys PATH[:asc|:desc][:nulls-first|:nulls-last] (store order when left out)")
    p.add_argument("--locale", metavar="NAME", help="locale for numbers, booleans and dates (canonical forms when left out)")
    p.add_argument("--no-grouping", action="store_true", help="no digit grouping with --locale")
    p.add_argument("--delimiter", metavar="CHAR", help="field delimiter, 'tab' for a tab (comma when left out)")
    p.add_argument("--null", metavar="TOKEN", help="text of null values (empty when left out)")
    p.add_argument("--no-header", action="store_true", help="do not write the header record")
    p.add_argument("--out", metavar="PATH", help="output file (standard output when left out or '-')")
    p.add_argument("--max-rows", type=int, metavar="N", help="records per file, needs --out (one file when left out)")


def _columns(spec, schema):
    if spec is None:
        return [(schema.field(n), n) for n in schema.names()]
    cols, names = [], set()
    for item in spec.split(","):
        path, eq, name = item.partition("=")
        path = path.strip()
        name = name.strip() if eq else path
        if not path or not name:
            raise UsageError(f"--columns: bad item {item!r}")
        field = schema.field(path)
        if name in names:
            raise UsageError(f"--columns: duplicate column name {name!r}")
        names.add(name)
        cols.append((field, name))
    return cols


def _target(path, number, width):
    name = path.name
    i = name.rfind(".")
    stem, suffix = (name[:i], name[i:]) if i > 0 else (name, "")
    return path.with_name(f"{stem}-{number:0{width}d}{suffix}")


def run(args, store) -> None:
    col = store.collection(args.collection)
    schema = col.schema
    columns = _columns(args.columns, schema)
    pred = parse_where(args.where, schema) if args.where is not None else None
    keys = parse_sort(args.sort, schema) if args.sort is not None else []
    locale = load_locale(args.locale) if args.locale is not None else None
    delim = check_delimiter(args.delimiter)
    null = check_null(args.null, delim)
    out = output_path(args.out)
    if args.max_rows is not None:
        if args.max_rows < 1:
            raise UsageError("--max-rows must be at least 1")
        if out is None:
            raise UsageError("--max-rows needs --out")

    records = [r for r in col.records() if pred is None or pred(r)]
    records = sort_records(records, keys)
    grouping = not args.no_grouping

    def line(cells):
        return delim.join(cells) + "\r\n"

    rows = []
    for r in records:
        cells = []
        for field, _ in columns:
            v = typed(r, field)
            cells.append(null if v is None else field_text(value_text(v, field, locale, grouping), delim, null))
        rows.append(line(cells))
    header = "" if args.no_header else line([field_text(n, delim, null) for _, n in columns])

    if out is None:
        write_stdout(header + "".join(rows))
        return
    n = args.max_rows
    if n is None or len(rows) <= n:
        write_text_file(out, header + "".join(rows))
        return
    chunks = [rows[i:i + n] for i in range(0, len(rows), n)]
    width = max(3, len(str(len(chunks))))
    for i, chunk in enumerate(chunks, 1):
        write_text_file(_target(out, i, width), header + "".join(chunk))
