"""Sort specifications of export --sort (docs/export.md, section 6)."""

from tally.errors import UsageError
from tally.store.values import typed


def parse_sort(text, schema):
    """-> list of (field, descending, nulls_first)."""
    keys, seen = [], set()
    for item in text.split(","):
        parts = [p.strip() for p in item.split(":")]
        path, rest = parts[0], parts[1:]
        if not path:
            raise UsageError(f"--sort: malformed key {item!r}")
        desc, placement = False, None
        if rest and rest[0] in ("asc", "desc"):
            desc = rest.pop(0) == "desc"
        if rest and rest[0] in ("nulls-first", "nulls-last"):
            placement = rest.pop(0) == "nulls-first"
        if rest:
            raise UsageError(f"--sort: malformed key {item!r}")
        field = schema.field(path)
        if path in seen:
            raise UsageError(f"--sort: {path} is repeated")
        seen.add(path)
        if placement is None:
            placement = desc  # nulls count as largest
        keys.append((field, desc, placement))
    return keys


def sort_records(records, keys):
    for field, desc, nulls_first in reversed(keys):
        pairs = [(typed(r, field), r) for r in records]
        nulls = [r for v, r in pairs if v is None]
        rest = [(v, r) for v, r in pairs if v is not None]
        rest.sort(key=lambda p: p[0], reverse=desc)
        body = [r for _, r in rest]
        records = nulls + body if nulls_first else body + nulls
    return records
