"""Text of typed values (docs/export.md, section 7) and CSV (section 8)."""

import re

from tally.errors import UsageError

_TOKENS = re.compile(r"YYYY|MM|M|DD|D|HH|H|hh|h|mm|ss|A")
_DATE_TOKENS = {"YYYY", "MM", "M", "DD", "D"}


def _pattern(pattern, d, date_only):
    def sub(m):
        t = m.group(0)
        if date_only and t not in _DATE_TOKENS:
            return t
        h12 = d.hour % 12 or 12 if not date_only else 0
        return {
            "YYYY": f"{d.year:04d}", "MM": f"{d.month:02d}", "M": str(d.month),
            "DD": f"{d.day:02d}", "D": str(d.day),
            "HH": f"{d.hour:02d}", "H": str(d.hour) if not date_only else "",
            "hh": f"{h12:02d}", "h": str(h12),
            "mm": f"{d.minute:02d}" if not date_only else "",
            "ss": f"{d.second:02d}" if not date_only else "",
            "A": ("AM" if d.hour < 12 else "PM") if not date_only else "",
        }[t]
    return _TOKENS.sub(sub, pattern)


def _group(digits, sizes, sep, min_grouping):
    if len(digits) < sizes[0] + min_grouping:
        return digits
    groups, i = [], 0
    rest = digits
    while rest:
        size = sizes[min(i, len(sizes) - 1)]
        groups.append(rest[-size:])
        rest = rest[:-size]
        i += 1
    return sep.join(reversed(groups))


def value_text(value, field, locale, grouping):
    t = field.type
    if t == "string":
        return value
    if t in ("int", "decimal"):
        if t == "int":
            neg, digits, frac = value < 0, str(abs(value)), None
        else:
            s = f"{abs(value):.{field.scale}f}"
            digits, _, frac = s.partition(".")
            neg = value < 0 and any(c not in "0" for c in digits + frac)
        if locale is None:
            return ("-" if neg else "") + digits + ("." + frac if frac is not None else "")
        if grouping:
            digits = _group(digits, locale.group_sizes, locale.group, locale.min_grouping)
        return (locale.minus if neg else "") + digits + (locale.decimal + frac if frac is not None else "")
    if t == "bool":
        if locale is None:
            return "true" if value else "false"
        return locale.true if value else locale.false
    if t == "date":
        if locale is None:
            return f"{value.year:04d}-{value.month:02d}-{value.day:02d}"
        return _pattern(locale.date, value, True)
    if locale is None:
        return value.strftime("%Y-%m-%dT%H:%M:%SZ") if value.year >= 1000 else (
            f"{value.year:04d}-{value.month:02d}-{value.day:02d}T{value.hour:02d}:{value.minute:02d}:{value.second:02d}Z")
    return _pattern(locale.datetime, value, False)


def check_delimiter(delim):
    if delim is None:
        return ","
    if delim == "tab":
        return "\t"
    if len(delim) != 1 or delim in ('"', "\r", "\n", " "):
        raise UsageError("--delimiter must be one character other than space, quote, CR or LF")
    return delim


def check_null(token, delim):
    if token is None:
        return ""
    if delim in token or any(c in token for c in '"\r\n'):
        raise UsageError("--null must not contain the delimiter, a quote, CR or LF")
    return token


def field_text(text, delim, null):
    needs = (delim in text or any(c in text for c in '"\r\n')
             or text[:1] in (" ", "\t") or text[-1:] in (" ", "\t") or text == null)
    if needs:
        return '"' + text.replace('"', '""') + '"'
    return text
